do $evidence$
declare actual_sha text;
begin
  if (select count(*) from _stackr_tcgcsv_english_rarity_facts) <> 442 then raise exception 'TCGCSV rarity fact count mismatch'; end if;
  select encode(extensions.digest(string_agg(concat_ws(chr(31),f.printing_id,f.set_id,f.set_code,f.collector_number,f.card_name,f.rarity_code,f.group_id,f.product_id,f.response_sha256,f.product_sha256),E'\n' order by concat_ws(chr(31),f.printing_id,f.set_id,f.set_code,f.collector_number,f.card_name,f.rarity_code,f.group_id,f.product_id,f.response_sha256,f.product_sha256)),'sha256'),'hex') into actual_sha from _stackr_tcgcsv_english_rarity_facts f;
  if actual_sha <> 'd11a947b4de7f7a866695f2c15eaedf3c6177fbd1b207590664ca146e85450b6' then raise exception 'TCGCSV rarity candidate hash mismatch: %', actual_sha; end if;
end
$evidence$;

do $precondition$
declare missing_rarity integer; missing_artist integer; distinct_gaps integer; resolved_count integer;
begin
  select count(*) filter (where p.rarity_id is null)::integer, count(*) filter (where nullif(btrim(p.artist),'') is null)::integer, count(*) filter (where p.rarity_id is null or nullif(btrim(p.artist),'') is null)::integer
  into missing_rarity,missing_artist,distinct_gaps from catalog.card_printings p where p.game_code='pokemon' and p.language_code='en' and p.deprecated_at is null;
  if missing_rarity <> 553 or missing_artist <> 544 or distinct_gaps <> 1027 then raise exception 'English metadata precondition mismatch: rarity %, artist %, rows %',missing_rarity,missing_artist,distinct_gaps; end if;
  select count(*)::integer into resolved_count from _stackr_tcgcsv_english_rarity_facts f join catalog.card_printings p on p.id=f.printing_id and p.set_id=f.set_id and p.game_code='pokemon' and p.language_code='en' and p.deprecated_at is null and p.collector_number=f.collector_number and p.english_display_name=f.card_name and p.rarity_id is null join catalog.sets s on s.id=p.set_id and s.set_code=f.set_code and s.deprecated_at is null join catalog.rarities r on r.game_code='pokemon' and r.code=f.rarity_code and r.deprecated_at is null;
  if resolved_count <> 442 then raise exception 'TCGCSV rarity exact resolution mismatch: %',resolved_count; end if;
end
$precondition$;

create temporary table _stackr_tcgcsv_english_rarity_changes on commit drop as
with resolved as (select f.*,r.id as rarity_id from _stackr_tcgcsv_english_rarity_facts f join catalog.rarities r on r.game_code='pokemon' and r.code=f.rarity_code and r.deprecated_at is null),
updated as (update catalog.card_printings p set rarity_id=resolved.rarity_id,updated_at=now() from resolved where p.id=resolved.printing_id and p.rarity_id is null returning p.id,resolved.*)
select * from updated;

do $changed$ begin if (select count(*) from _stackr_tcgcsv_english_rarity_changes) <> 442 then raise exception 'TCGCSV rarity change count mismatch'; end if; end $changed$;

insert into audit.catalogue_events (request_id,actor_role,event_type,entity_schema,entity_table,entity_id,canonical_key,event_payload,internal_notes)
select 'catalogue-rarity-en-tcgcsv:2026-08-21:d11a947b4de7f7a8','catalogue_migration','catalogue_printing_rarity_backfilled','catalog','card_printings',c.id,concat('pokemon:en:',c.set_code,':',c.collector_number),jsonb_build_object('languageCode','en','setCode',c.set_code,'collectorNumber',c.collector_number,'cardName',c.card_name,'rarityCode',c.rarity_code,'sourceCode','tcgcsv_tcgplayer','sourceUrl',c.source_url,'groupId',c.group_id,'groupName',c.group_name,'productId',c.product_id,'productName',c.product_name,'productNumber',c.product_number,'productRarity',c.product_rarity,'sourceResponseSha256',c.response_sha256,'sourceProductSha256',c.product_sha256,'candidateSha256','d11a947b4de7f7a866695f2c15eaedf3c6177fbd1b207590664ca146e85450b6','evidenceSha256','9986511d331d45314d51ffb559e8e68b67ffafbd246b8dfdd9a51743ae6a48b8'),'Reviewed set-to-group mapping plus exact collector number and card name; null-only rarity backfill.' from _stackr_tcgcsv_english_rarity_changes c;

insert into catalog.catalogue_change_log (entity_schema,entity_table,entity_id,change_type,mobile_syncable,public_change_summary)
select 'catalog','card_printings',c.id,'update',true,jsonb_build_object('field','rarity_id','rarityCode',c.rarity_code,'languageCode','en','sourceCode','tcgcsv_tcgplayer') from _stackr_tcgcsv_english_rarity_changes c;

do $postcondition$
declare missing_rarity integer; missing_artist integer; distinct_gaps integer;
begin
  if exists (select 1 from _stackr_tcgcsv_english_rarity_changes c join catalog.card_printings p on p.id=c.id join catalog.rarities r on r.id=p.rarity_id where r.code is distinct from c.rarity_code) then raise exception 'TCGCSV rarity row postcondition failed'; end if;
  select count(*) filter (where p.rarity_id is null)::integer, count(*) filter (where nullif(btrim(p.artist),'') is null)::integer, count(*) filter (where p.rarity_id is null or nullif(btrim(p.artist),'') is null)::integer into missing_rarity,missing_artist,distinct_gaps from catalog.card_printings p where p.game_code='pokemon' and p.language_code='en' and p.deprecated_at is null;
  if missing_rarity <> 111 or missing_artist <> 544 or distinct_gaps <> 651 then raise exception 'English metadata postcondition mismatch: rarity %, artist %, rows %',missing_rarity,missing_artist,distinct_gaps; end if;
end
$postcondition$;
